// repository
async findByIdForAllow(id, accessContext): Promise<boolean> {
  const { where, joins } = engine.resolveUpdate(
    accessContext.effectiveRoles,
    "<entity>",
    accessContext.subjects,
  );
  let q = db.select({ id: <table>.id }).from(<table>);
  for (const j of joins) q = q.leftJoin(j.table, j.on);
  const rows = await q.where(and(eq(<table>.id, id), where));
  return rows.length > 0;
}

